    <p>This is a dialog content.</p>
</dialog>

<script>
    // اگر مودال را نشات کنید، این فعالیت را ویرایش کنید
    document.getElementById('myDialog').addEventListener('show', () => {
        document.getElementById('dialog').style.display = 'block';
    });

    // اگر مودال را نشات کنید، این فعالیت را ویرایش کنید
    document.getElementById('myDialog').addEventListener('hide', () => {
        document.getElementById('dialog').style.display = 'none';
    });
</script>

</body>
</html>
```

